<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal();$pdo=db();$pageTitle='Caixa';$cash=open_cash();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';
 if($action==='open'&&!$cash){$v=number_value($_POST['valor_inicial']??0);$pdo->prepare('INSERT INTO caixas(usuario_abertura_id,abertura_em,valor_inicial,status) VALUES(?,?,?,?)')->execute([current_user()['id'],now(),$v,'Aberto']);log_action('abertura de caixa');flash('success','Caixa aberto com sucesso.');redirect('index.php');}
 if($action==='move'&&$cash){$type=$_POST['tipo']??'Entrada manual';$v=number_value($_POST['valor']??0);$d=trim($_POST['descricao']??'');if($v<=0)$error='Valor inválido.';else{add_cash_movement($cash['id'],$type,$v,$d,current_user()['id']);log_action('movimentação de caixa',$type);flash('success','Movimentação registrada.');redirect('index.php');}}
 if($action==='close'&&$cash){$st=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN m.tipo='Dinheiro' THEN m.valor ELSE 0 END),0) dinheiro,COALESCE(SUM(CASE WHEN m.tipo='PIX' THEN m.valor ELSE 0 END),0) pix,COALESCE(SUM(CASE WHEN m.tipo='Débito' THEN m.valor ELSE 0 END),0) debito,COALESCE(SUM(CASE WHEN m.tipo='Crédito' THEN m.valor ELSE 0 END),0) credito,COALESCE(SUM(CASE WHEN m.tipo IN ('Sangria','Despesa') THEN m.valor ELSE 0 END),0) saidas,COALESCE(SUM(CASE WHEN m.tipo NOT IN ('Dinheiro','PIX','Débito','Crédito','Sangria','Despesa') THEN m.valor ELSE 0 END),0) outras FROM movimentacoes_caixa m WHERE m.caixa_id=?");$st->execute([$cash['id']]);$sum=$st->fetch();$expected=(float)$cash['valor_inicial']+(float)$sum['dinheiro']+(float)$sum['outras']-(float)$sum['saidas'];$informed=number_value($_POST['valor_informado']??0);$diff=$informed-$expected;$pdo->prepare("UPDATE caixas SET status='Fechado',fechamento_em=?,usuario_fechamento_id=?,valor_informado=?,valor_esperado=?,diferenca=? WHERE id=?")->execute([now(),current_user()['id'],$informed,$expected,$diff,$cash['id']]);log_action('fechamento de caixa','caixas',$cash['id']);flash('success','Caixa fechado.');redirect('index.php');}}
$cash=open_cash();$sum=$cash?null:null;if($cash){$st=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN tipo='Dinheiro' THEN valor ELSE 0 END),0) dinheiro,COALESCE(SUM(CASE WHEN tipo='PIX' THEN valor ELSE 0 END),0) pix,COALESCE(SUM(CASE WHEN tipo='Débito' THEN valor ELSE 0 END),0) debito,COALESCE(SUM(CASE WHEN tipo='Crédito' THEN valor ELSE 0 END),0) credito,COALESCE(SUM(CASE WHEN tipo IN ('Sangria','Despesa') THEN valor ELSE 0 END),0) saidas FROM movimentacoes_caixa WHERE caixa_id=?");$st->execute([$cash['id']]);$sum=$st->fetch();$mov=$pdo->prepare('SELECT m.*,u.nome usuario_nome,v.numero venda_numero FROM movimentacoes_caixa m JOIN usuarios u ON u.id=m.usuario_id LEFT JOIN vendas v ON v.id=m.venda_id WHERE m.caixa_id=? ORDER BY m.id DESC');$mov->execute([$cash['id']]);$mov=$mov->fetchAll();}
$closed=$pdo->query("SELECT c.*,u.nome abertura_usuario FROM caixas c JOIN usuarios u ON u.id=c.usuario_abertura_id WHERE c.status='Fechado' ORDER BY c.id DESC LIMIT 20")->fetchAll();include __DIR__.'/../../includes/header.php'; ?>
<div class="page-head"><h1>Caixa</h1></div><?php if($error): ?><div class="alert danger"><?=e($error)?></div><?php endif; ?>
<?php if(!$cash): ?><div class="card"><h3>Abertura do caixa</h3><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="open"><div class="field"><label>Valor inicial</label><input type="number" step="0.01" min="0" name="valor_inicial" value="0"></div><button class="btn primary">Abrir caixa</button></form></div>
<?php else: ?><div class="grid grid-4"><div class="card stat"><span class="label">Dinheiro</span><span class="value"><?=money($sum['dinheiro'])?></span></div><div class="card stat"><span class="label">PIX</span><span class="value"><?=money($sum['pix'])?></span></div><div class="card stat"><span class="label">Débito</span><span class="value"><?=money($sum['debito'])?></span></div><div class="card stat"><span class="label">Crédito</span><span class="value"><?=money($sum['credito'])?></span></div></div><div class="grid grid-3" style="margin-top:16px"><div class="card"><h3>Caixa aberto</h3><p>Abertura: <?=datetime_br($cash['abertura_em'])?></p><p>Valor inicial: <strong><?=money($cash['valor_inicial'])?></strong></p><?=status_badge('Aberto')?></div><div class="card"><h3>Nova movimentação</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="move"><div class="field"><label>Tipo</label><select name="tipo"><option>Entrada manual</option><option>Suprimento</option><option>Sangria</option><option>Despesa</option><option>Ajuste</option><option>Outro movimento</option></select></div><div class="field"><label>Valor</label><input type="number" step="0.01" min="0.01" name="valor" required></div><div class="field"><label>Descrição</label><input name="descricao"></div><button class="btn secondary" style="margin-top:8px">Registrar</button></form></div><div class="card"><h3>Fechamento</h3><p class="muted">O valor esperado considera o dinheiro físico: valor inicial + vendas em dinheiro + outras entradas em caixa − sangrias/despesas.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="close"><div class="field"><label>Valor informado em dinheiro</label><input type="number" step="0.01" min="0" name="valor_informado" required></div><button class="btn danger" style="margin-top:8px" onclick="return confirmAction('Fechar o caixa atual?')">Fechar caixa</button></form></div></div><div class="card" style="margin-top:16px"><h3>Movimentações atuais</h3><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Tipo</th><th>Descrição</th><th>Valor</th><th>Venda</th><th>Usuário</th></tr></thead><tbody><?php foreach($mov as $m): ?><tr><td><?=datetime_br($m['data_hora'])?></td><td><?=e($m['tipo'])?></td><td><?=e($m['descricao'])?></td><td><?=money($m['valor'])?></td><td><?=e($m['venda_numero'])?></td><td><?=e($m['usuario_nome'])?></td></tr><?php endforeach;if(!$mov): ?><tr><td colspan="6" class="empty">Sem movimentações.</td></tr><?php endif;?></tbody></table></div></div><?php endif; ?>
<div class="card" style="margin-top:16px"><h3>Caixas fechados</h3><div class="table-wrap"><table class="table"><thead><tr><th>Caixa</th><th>Abertura</th><th>Fechamento</th><th>Esperado</th><th>Informado</th><th>Diferença</th></tr></thead><tbody><?php foreach($closed as $c): ?><tr><td>#<?=$c['id']?></td><td><?=datetime_br($c['abertura_em'])?></td><td><?=datetime_br($c['fechamento_em'])?></td><td><?=money($c['valor_esperado'])?></td><td><?=money($c['valor_informado'])?></td><td class="<?=abs($c['diferenca'])>.009?'danger-text':'success-text'?>"><?=money($c['diferenca'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php include __DIR__.'/../../includes/footer.php'; ?>
